# frozen_string_literal: true

# T-36 — a deterministic, engine-neutral snapshot of the database schema.
#
# Run inside a Redmine checkout: `bundle exec rails runner <this file> [out_path]`
# (`script/migrate_updown.sh` is the only caller that matters).
#
# --- WHY NOT `rake db:schema:dump` ---
#
# `db/schema.rb` is Rails-version-dependent in ways that have nothing to do with this
# plugin: `t.datetime` gained a default precision in Rails 7, `create_table` gained and
# lost options across 6.1 → 8.1, and the file is regenerated by Redmine's own
# `redmine:plugins:migrate` task (`lib/tasks/redmine.rake:155`) — so it is both noisy and
# already written by the thing under test. It is also PostgreSQL/MySQL-divergent for
# column defaults.
#
# This emits sorted lines instead. Diffing two of them says WHICH object appeared or
# disappeared, in one line, on any of the three engines this plugin runs on.
#
# --- WHAT IS AND IS NOT NORMALISED ---
#
# `sql_type` is kept verbatim, because the whole point of a down-migration test is to
# notice a column that came back as a different type. Column DEFAULTS are kept too. What is
# normalised is only ORDER: tables, columns within a table, and indexes are each sorted, so
# a snapshot does not depend on the order the database happens to list things in — which is
# not stable on any of the three engines (CLAUDE.md §6).
#
# `schema_migrations` rows for THIS PLUGIN are emitted as `PLUGINMIGRATION` lines. FR-69
# asks for "no plugin row in `plugin_schema_info`"; that table does not exist on any
# supported Redmine (measured — see `script/migrate_updown.sh`), and the real bookkeeping is
# a `schema_migrations` row of the form `<version>-<plugin_id>`
# (`redmine/lib/redmine/plugin.rb:553-555`). Emitting them here is what lets the caller
# assert the requirement's INTENT against the mechanism that actually exists.

PLUGIN_ID = 'redmine_reporter_dashboards'

connection = ActiveRecord::Base.connection
lines = []

connection.tables.sort.each do |table|
  lines << "TABLE #{table}"

  connection.columns(table).sort_by(&:name).each do |column|
    lines << format(
      'COLUMN %<table>s.%<name>s type=%<sql_type>s null=%<null>s default=%<default>s',
      table: table, name: column.name, sql_type: column.sql_type,
      null: column.null, default: column.default.inspect
    )
  end

  connection.indexes(table).sort_by(&:name).each do |index|
    lines << format(
      'INDEX %<table>s.%<name>s unique=%<unique>s columns=%<columns>s',
      table: table, name: index.name, unique: index.unique,
      columns: Array(index.columns).join(',')
    )
  end
end

# WHERE THE MIGRATION BOOKKEEPING LIVES MOVED INSIDE THE SUPPORT SPAN, and getting this
# wrong would have failed exactly one CI cell.
#
#   Rails 6.1 (Redmine 5.1)   `ActiveRecord::Base.connection.schema_migration`
#   Rails 7.1+ (Redmine 6.0+) `ActiveRecord::Base.connection.pool.schema_migration`
#
# Redmine's own migrator tracks the move: 5.1-stable's `lib/redmine/plugin.rb:518` passes
# `connection.schema_migration`, 6.1-stable's `:529` passes `connection.pool.schema_migration`.
# The first version of this file used the pool form unconditionally, so the `migrate-updown`
# job would have raised `NoMethodError` on Redmine 5.1 — the one branch nothing else here
# can exercise locally, and therefore the one where a version-specific mistake survives.
#
# Asked with `respond_to?` rather than of `Rails::VERSION`, because the question is "does
# this object answer" and that is what the two branches actually differ on.
schema_migration =
  if connection.pool.respond_to?(:schema_migration)
    connection.pool.schema_migration
  elsif connection.respond_to?(:schema_migration)
    connection.schema_migration
  else
    ActiveRecord::SchemaMigration
  end

# Deliberately only this plugin's rows: another plugin's migrations are not this job's
# business, and including them would make the comparison fail for somebody else's reason.
sm_table = connection.quote_table_name(schema_migration.table_name)
connection.select_values("SELECT version FROM #{sm_table}")
          .select { |v| v.to_s.end_with?("-#{PLUGIN_ID}") }
          .sort
          .each { |v| lines << "PLUGINMIGRATION #{v}" }

output = "#{lines.join("\n")}\n"

path = ARGV[0]
if path && !path.empty?
  File.binwrite(path, output)
else
  $stdout.write(output)
end
